	NeifaVS() : ZeroCardViewAsSkill("neifa")
	{
	}

	const Card*viewAs() const
	{
		QString pattern = Sanguosha->currentRoomState()->getCurrentCardUsePattern();
		if (pattern == "@@neifa")
			return new NeifaCard;
		else
			return new ExtraCollateralCard;
	}

