class Moushi : public TriggerSkill
{
public:
	Moushi() : TriggerSkill("moushi")
	{
		events << EventPhaseChanging << Death << Damage;
		view_as_skill = new MoushiVS;
	}

	bool triggerable(const ServerPlayer*target) const
	{
		return target != nullptr;
	}

	bool trigger(TriggerEvent event, Room*room, ServerPlayer*player, QVariant &data) const
	{
		ServerPlayer*current = room->getCurrent();
		if (event == EventPhaseChanging){
			if (!current || current != player) return false;
			PhaseChangeStruct change = data.value<PhaseChangeStruct>();
			if (change.from != Player::Play) return false;
			room->setPlayerProperty(player, "moushi_from", QStringList());
			room->setPlayerMark(player, "&moushi", 0);
		} else if (event == Damage){
			if (player->isDead() || !current || current != player || player->getPhase() != Player::Play) return false;
			QStringList names = player->property("moushi_from").toStringList();
			if (names.isEmpty()) return false;

			DamageStruct damage = data.value<DamageStruct>();
			if (player->getMark("moushi_" + damage.to->objectName() + "-Clear") > 0) return false;
			room->addPlayerMark(player, "moushi_" + damage.to->objectName() + "-Clear");

			QList<ServerPlayer*> xunchens;
			foreach(QString str, names){
				ServerPlayer*xunchen = room->findPlayerByObjectName(str);
				if (xunchen && xunchen->isAlive() && xunchen->hasSkill(objectName()))
					xunchens << xunchen;
			}
			if (xunchens.isEmpty()) return false;

			room->sortByActionOrder(xunchens);
			foreach(ServerPlayer*p, xunchens){
				if (p->isAlive() && p->hasSkill(objectName())){
					room->sendCompulsoryTriggerLog(p, objectName(), true, true);
					p->drawCards(1, objectName());
				}
			}
		} else {
			DeathStruct death = data.value<DeathStruct>();
			room->setPlayerProperty(death.who, "moushi_from", QStringList());
			room->setPlayerMark(death.who, "&moushi", 0);
		}
		return false;
	}
};

class Bizheng : public TriggerSkillV2
{
public:
	Bizheng() : TriggerSkillV2("bizheng") { events << EventPhaseEnd; }
	TriggerList triggerable(TriggerEvent, Room *room, ServerPlayer *player, QVariant &) const override
	{
		TriggerList result;
		if (player && player->isAlive() && player->getPhase() == Player::Draw && player->hasSkill(objectName())
			&& !room->getOtherPlayers(player).isEmpty()) result[player] << objectName();
		return result;
	}
	bool cost(TriggerEvent, Room *room, ServerPlayer *, SkillContext &ctx) const override
	{
		if (!ctx.owner) return false;
		ServerPlayer *target = room->askForPlayerChosen(ctx.owner, room->getOtherPlayers(ctx.owner),
			objectName(), "@bizheng-invoke", true, true);
		if (!target) return false;
		ctx.targets << target;
		ctx.manual_effect = true;
		return true;
	}
	bool effect(TriggerEvent event, Room *room, ServerPlayer *player, SkillContext &ctx) const override
	{
		room->broadcastSkillInvoke(objectName());
		ServerPlayer *recipient = ctx.targets.value(0);
		if (!recipient) return false;
		ctx.choice = "draw";
		if (skillEffect(event, room, player, ctx, recipient)) return true;
		QList<ServerPlayer *> affected{ctx.owner, recipient};
		room->sortByActionOrder(affected);
		ctx.choice = "discard";
		// Each player's hand threshold and target cancellation is evaluated independently.
		for (ServerPlayer *target : affected)
			if (target->isAlive() && target->getHandcardNum() > target->getMaxHp()
				&& skillEffect(event, room, player, ctx, target)) return true;
		return false;
	}
	bool effectTarget(TriggerEvent, Room *room, ServerPlayer *, SkillContext &ctx, ServerPlayer *target) const override
	{
		const int amount = 2 * getEffectiveAmount(ctx);
		if (ctx.choice == "draw") target->drawCards(amount, objectName());
		else if (target->getHandcardNum() > target->getMaxHp())
			room->askForDiscard(target, objectName(), amount, amount, false, true);
		return false;
	}
};

